  const lang = getLang(c);
  const featuredMovies = await db.select().from(movies).where(and2(eq2(movies.isPublished, true), eq2(movies.featured, true))).limit(3);
  const featuredSeries = await db.select().from(series).where(and2(eq2(series.isPublished, true), eq2(series.featured, true))).limit(3);
