  const mGenres = await db.select({ slug: genres.slug, name: genres.name }).from(movieGenres).innerJoin(genres, eq2(movieGenres.genreId, genres.id)).where(eq2(movieGenres.movieId, movie.id));
  const cast = await db.select({
    id: persons.id,
    name: persons.name,
    photoUrl: persons.photoUrl,
    role: movieCast.role,
    characterName: movieCast.characterName
  }).from(movieCast).innerJoin(persons, eq2(movieCast.personId, persons.id)).where(eq2(movieCast.movieId, movie.id)).orderBy(movieCast.sortOrder);
  const movieReviews = await db.select({
    id: reviews.id,
    rating: reviews.rating,
    text: reviews.text,
    createdAt: reviews.createdAt,
    userName: users.name,
    userAvatar: users.avatarLetter
  }).from(reviews).innerJoin(users, eq2(reviews.userId, users.id)).where(eq2(reviews.movieId, movie.id)).orderBy(desc2(reviews.createdAt)).limit(20);
  const genreIds = mGenres.map((g) => g.slug);
