// apps/api/src/routes/series.ts
var seriesRoute = new Hono2();
function locSeries2(s, lang) {
  return localizeObj(s, lang, ["title", "description", "shortDesc", "country"]);
}
seriesRoute.get("/", async (c) => {
  const db = getDb();
  const lang = getLang(c);
  const pagination = getPagination(c);
  const conditions = [eq2(series.isPublished, true)];
  const genreSlug = c.req.query("genre");
  let genreSeriesIds = null;
  if (genreSlug) {
    const [genre] = await db.select().from(genres).where(eq2(genres.slug, genreSlug));
    if (genre) {
      const links = await db.select().from(seriesGenres).where(eq2(seriesGenres.genreId, genre.id));
      genreSeriesIds = links.map((l) => l.seriesId);
      if (genreSeriesIds.length === 0) {
        return c.json(paginatedResponse([], 0, pagination));
      }
    }
  }
  const year = c.req.query("year");
  if (year) conditions.push(eq2(series.year, parseInt(year)));
  const sort = c.req.query("sort") || "new";
  let orderBy;
  switch (sort) {
    case "rating":
      orderBy = desc2(series.rating);
      break;
    case "year":
      orderBy = desc2(series.year);
      break;
    default:
      orderBy = desc2(series.createdAt);
  }
  let allResults;
  if (genreSeriesIds) {
    allResults = await db.select().from(series).where(and2(...conditions, inArray2(series.id, genreSeriesIds))).orderBy(orderBy);
  } else {
    allResults = await db.select().from(series).where(and2(...conditions)).orderBy(orderBy);
  }
  const total = allResults.length;
  const paged = allResults.slice(pagination.offset, pagination.offset + pagination.limit);
  const result = [];
  for (const s of paged) {
    const sGenres = await db.select({ slug: genres.slug, name: genres.name }).from(seriesGenres).innerJoin(genres, eq2(seriesGenres.genreId, genres.id)).where(eq2(seriesGenres.seriesId, s.id));
    const sSeasons = await db.select().from(seasons).where(eq2(seasons.seriesId, s.id));
    let episodeCount = 0;
    for (const season of sSeasons) {
      const eps = await db.select().from(episodes).where(eq2(episodes.seasonId, season.id));
      episodeCount += eps.length;
    }
    result.push({
      ...locSeries2(s, lang),
      genres: sGenres.map((g) => ({ slug: g.slug, name: localizeObj(g, lang, ["name"]).name })),
      seasonCount: sSeasons.length,
      episodeCount
    });
  }
  return c.json(paginatedResponse(result, total, pagination));
});
seriesRoute.get("/:slug", async (c) => {
  const db = getDb();
  const lang = getLang(c);
  const slug = c.req.param("slug");
  const [show] = await db.select().from(series).where(eq2(series.slug, slug));
  if (!show) return c.json({ error: "Series not found" }, 404);
  const sGenres = await db.select({ slug: genres.slug, name: genres.name }).from(seriesGenres).innerJoin(genres, eq2(seriesGenres.genreId, genres.id)).where(eq2(seriesGenres.seriesId, show.id));
  const cast = await db.select({
    id: persons.id,
    name: persons.name,
    photoUrl: persons.photoUrl,
    role: seriesCast.role,
    characterName: seriesCast.characterName
  }).from(seriesCast).innerJoin(persons, eq2(seriesCast.personId, persons.id)).where(eq2(seriesCast.seriesId, show.id)).orderBy(seriesCast.sortOrder);
  const allSeasons = await db.select().from(seasons).where(eq2(seasons.seriesId, show.id)).orderBy(seasons.number);
  const seasonsWithEpisodes = [];
  for (const season of allSeasons) {
    const eps = await db.select().from(episodes).where(eq2(episodes.seasonId, season.id)).orderBy(episodes.number);
    seasonsWithEpisodes.push({
      ...localizeObj(season, lang, ["title", "description"]),
      episodes: eps.map((ep) => localizeObj(ep, lang, ["title", "description"]))
    });
  }
  const seriesReviews = await db.select({
    id: reviews.id,
    rating: reviews.rating,
    text: reviews.text,
    createdAt: reviews.createdAt,
    userName: users.name,
    userAvatar: users.avatarLetter
  }).from(reviews).innerJoin(users, eq2(reviews.userId, users.id)).where(eq2(reviews.seriesId, show.id)).orderBy(desc2(reviews.createdAt)).limit(20);
  const genreSlugs = sGenres.map((g) => g.slug);
  const similarLinks = await db.select({ seriesId: seriesGenres.seriesId }).from(seriesGenres).innerJoin(genres, eq2(seriesGenres.genreId, genres.id)).where(and2(
    inArray2(genres.slug, genreSlugs),
    ne2(seriesGenres.seriesId, show.id)
  ));
  const similarIds = [...new Set(similarLinks.map((l) => l.seriesId))].slice(0, 6);
  const similar = similarIds.length > 0 ? await db.select().from(series).where(and2(inArray2(series.id, similarIds), eq2(series.isPublished, true))) : [];
  return c.json({
    ...locSeries2(show, lang),
    genres: sGenres.map((g) => ({ slug: g.slug, name: localizeObj(g, lang, ["name"]).name })),
    cast: cast.map((p) => localizeObj(p, lang, ["name", "characterName"])),
    seasons: seasonsWithEpisodes,
    reviews: seriesReviews.map((r) => ({
      ...r,
      userName: localizeObj({ userName: r.userName }, lang, ["userName"]).userName
    })),
    similar: similar.map((s) => locSeries2(s, lang))
  });
});
