// apps/api/src/routes/search.ts
var searchRoute = new Hono2();
searchRoute.get("/", async (c) => {
  const db = getDb();
  const lang = getLang(c);
  const q = (c.req.query("q") || "").trim().toLowerCase();
  if (!q || q.length < 2) {
    return c.json({ results: [], query: q });
  }
  const movieResults = await db.select().from(movies).where(
    and2(
      eq2(movies.isPublished, true),
      sql2`(${movies.title}->>'ru' ILIKE ${"%" + q + "%"} OR ${movies.title}->>'uz' ILIKE ${"%" + q + "%"})`
    )
  ).limit(10);
  const seriesResults = await db.select().from(series).where(
    and2(
      eq2(series.isPublished, true),
      sql2`(${series.title}->>'ru' ILIKE ${"%" + q + "%"} OR ${series.title}->>'uz' ILIKE ${"%" + q + "%"})`
    )
  ).limit(10);
  const personResults = await db.select().from(persons).where(
    sql2`(${persons.name}->>'ru' ILIKE ${"%" + q + "%"} OR ${persons.name}->>'uz' ILIKE ${"%" + q + "%"})`
  ).limit(5);
  const results = [
    ...movieResults.map((m) => ({
      type: "movie",
      id: m.id,
      slug: m.slug,
      title: localizeObj(m, lang, ["title"]).title,
      year: m.year,
      rating: m.rating,
      posterUrl: m.posterUrl
    })),
    ...seriesResults.map((s) => ({
      type: "series",
      id: s.id,
      slug: s.slug,
      title: localizeObj(s, lang, ["title"]).title,
      year: s.year,
      rating: s.rating,
      posterUrl: s.posterUrl
    })),
    ...personResults.map((p) => ({
      type: "person",
      id: p.id,
      name: localizeObj(p, lang, ["name"]).name,
      photoUrl: p.photoUrl
    }))
  ];
  return c.json({ results, query: q, total: results.length });
});
