usersRoute.get("/:id/history", async (c) => {
  const db = getDb();
  const lang = getLang(c);
  const userId = c.req.param("id");
  const onlyContinue = c.req.query("continue") === "true";
  let historyItems = await db.select().from(watchHistory).where(eq2(watchHistory.userId, userId)).orderBy(desc2(watchHistory.watchedAt));
  if (onlyContinue) {
    historyItems = historyItems.filter((h) => parseFloat(String(h.progressPct)) < 95);
  }
  const result = [];
  for (const h of historyItems) {
    let content = null;
    if (h.movieId) {
      const [m] = await db.select().from(movies).where(eq2(movies.id, h.movieId));
      if (m) content = { type: "movie", ...localizeObj(m, lang, ["title"]) };
    }
    if (h.episodeId) {
      const [ep] = await db.select().from(episodes).where(eq2(episodes.id, h.episodeId));
      if (ep) {
        const [sn] = await db.select().from(seasons).where(eq2(seasons.id, ep.seasonId));
        let showTitle = "";
        if (sn) {
          const [show] = await db.select().from(series).where(eq2(series.id, sn.seriesId));
          if (show) showTitle = localizeObj(show, lang, ["title"]).title;
        }
        content = {
          type: "episode",
          ...localizeObj(ep, lang, ["title"]),
          seriesTitle: showTitle,
          seasonNumber: sn?.number
        };
      }
    }
    if (content) {
      result.push({
        ...content,
        progressSec: h.progressSec,
        durationSec: h.durationSec,
        progressPct: h.progressPct,
        watchedAt: h.watchedAt
      });
    }
  }
  return c.json(result);
});
