usersV2.post("/:id/profiles", async (c) => {
  const db = getDb();
  const userId = c.req.param("id");
  const body = await c.req.json();
  const [user] = await db.select().from(users).where(eq2(users.id, userId));
  if (!user) return c.json({ error: "User not found" }, 404);
  const existing = await db.select().from(userProfiles).where(eq2(userProfiles.userId, userId));
  let maxProfiles = 1;
  if (user.planId) {
    const [plan] = await db.select().from(plans).where(eq2(plans.id, user.planId));
    if (plan) maxProfiles = plan.maxProfiles || 1;
  }
  if (existing.length >= maxProfiles) {
    return c.json({ error: `\u041C\u0430\u043A\u0441\u0438\u043C\u0443\u043C ${maxProfiles} \u043F\u0440\u043E\u0444\u0438\u043B\u0435\u0439 \u043D\u0430 \u0432\u0430\u0448\u0435\u043C \u0442\u0430\u0440\u0438\u0444\u0435` }, 403);
  }
  const [profile] = await db.insert(userProfiles).values({
    userId,
    name: body.name,
    isKids: body.isKids || false,
    avatarUrl: body.avatarUrl,
    isDefault: existing.length === 0
  }).returning();
  return c.json(profile, 201);
});
