usersV2.get("/:id/downloads", async (c) => {
  const db = getDb();
  const lang = getLang(c);
  const userId = c.req.param("id");
  const items = await db.select().from(downloads).where(eq2(downloads.userId, userId)).orderBy(desc2(downloads.downloadedAt));
  const result = [];
  for (const d of items) {
    let content = null;
    if (d.movieId) {
      const [m] = await db.select().from(movies).where(eq2(movies.id, d.movieId));
      if (m) content = { type: "movie", ...localizeObj(m, lang, ["title"]), fileSize: d.fileSize };
    }
    if (d.episodeId) {
      const [ep] = await db.select().from(episodes).where(eq2(episodes.id, d.episodeId));
      if (ep) {
        const [sn] = await db.select().from(seasons).where(eq2(seasons.id, ep.seasonId));
        let seriesTitle = "";
        if (sn) {
          const [show] = await db.select().from(series).where(eq2(series.id, sn.seriesId));
          if (show) seriesTitle = localizeObj(show, lang, ["title"]).title;
        }
        content = {
          type: "episode",
          ...localizeObj(ep, lang, ["title"]),
          seriesTitle,
          seasonNumber: sn?.number,
          fileSize: d.fileSize
        };
      }
    }
    if (content) result.push({ ...content, downloadedAt: d.downloadedAt, downloadId: d.id });
  }
  return c.json(result);
});
usersV2.post("/:id/downloads", async (c) => {
  const db = getDb();
  const userId = c.req.param("id");
  const body = await c.req.json();
  const [dl] = await db.insert(downloads).values({
    userId,
    movieId: body.movieId || null,
    episodeId: body.episodeId || null,
    fileSize: body.fileSize || 0
  }).returning();
  return c.json(dl, 201);
});
usersV2.delete("/:id/downloads/:did", async (c) => {
  const db = getDb();
  const did = c.req.param("did");
  await db.delete(downloads).where(eq2(downloads.id, did));
  return c.json({ ok: true });
});
usersV2.post("/broadcast/notifications", async (c) => {
  const db = getDb();
  const secret = c.req.header("X-Admin-Secret");
  const expected = process.env.ADMIN_SECRET || "changeme-makontv-admin-2025";
  if (secret !== expected) return c.json({ error: "Unauthorized" }, 401);
  const body = await c.req.json();
  const allUsers = await db.select({ id: users.id }).from(users).where(eq2(users.isBlocked, false));
  let count = 0;
  for (const u of allUsers) {
    await db.insert(notifications).values({
      userId: u.id,
      type: body.type,
      title: body.title,
      body: body.body || {},
      iconType: body.iconType,
      actionUrl: body.actionUrl
    });
    count++;
  }
  return c.json({ ok: true, sentTo: count });
});
