analytics.get("/revenue", async (c) => {
  const db = getDb();
  const activeSubs = await db.select({
    planId: users.planId,
    count: sql2`count(*)`
  }).from(users).where(eq2(users.subscriptionStatus, "active")).groupBy(users.planId);
  let monthlyRevenue = 0;
  const breakdown = [];
  for (const sub of activeSubs) {
    if (sub.planId) {
      const [plan] = await db.select().from(plans).where(eq2(plans.id, sub.planId));
      if (plan && plan.price > 0) {
        const subtotal = plan.price * sub.count;
        monthlyRevenue += subtotal;
        breakdown.push({
          plan: plan.name,
          price: plan.price,
          subscribers: sub.count,
          monthlyTotal: subtotal
        });
      }
    }
  }
  return c.json({
    monthlyRevenue,
    annualProjected: monthlyRevenue * 12,
    currency: "UZS",
    breakdown
  });
});
